-- A person's statements: how many have been taken, and the due-total and date (the sheet's today) of
-- the last one. The last due-total is null with no statement, or when it was n/a.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN statement_total DECIMAL(14, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: stated, with the due figure it had then (null when
-- it was n/a). A claim that did not count at the statement is left unbound, its due live again.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
-- Each statement taken for a person, numbered from 1 in the order taken, with its due-total (null
-- when n/a) and date (the sheet's today). Cancelling the last statement removes its row, and the
-- person shows the one before it again. A person's last statement taken before this table is kept
-- here; any earlier ones were not recorded, so cancelling back past it shows no statement.
CREATE TABLE person_statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    seq       INT            NOT NULL,
    total     DECIMAL(14, 2),
    taken_on  DATE           NOT NULL,
    UNIQUE (person_id, seq)
);
INSERT INTO person_statement (sheet_id, person_id, seq, total, taken_on)
    SELECT sheet_id, id, statement_count, statement_total, statement_date
    FROM person WHERE statement_count > 0 AND statement_date IS NOT NULL;
package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.person.PersonController.PersonView;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people/{personId}/statements")
@Validated
public class StatementController {

    /** What the screen is told after a statement: the person and their claims, newest first. */
    public record StatementView(PersonView person, List<ClaimView> claims) {
    }

    private final StatementService service;

    public StatementController(StatementService service) {
        this.service = service;
    }

    /** The date a statement is taken as of; with none, the sheet's today. */
    public record StatementForm(LocalDate asOf) {
    }

    /** Take a statement for a person, as of a date on or before the sheet's today. */
    @PostMapping
    public StatementView take(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody(required = false) StatementForm form) {
        StatementService.Stated stated = service.take(sheetId, SignedIn.name(user), personId,
                form == null ? null : form.asOf());
        return new StatementView(PersonView.of(stated.person()),
                stated.claims().stream().map(ClaimView::of).toList());
    }

    /** Cancel the person's last statement. */
    @DeleteMapping("/last")
    public StatementView cancel(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        StatementService.Stated stated = service.cancel(sheetId, SignedIn.name(user), personId);
        return new StatementView(PersonView.of(stated.person()),
                stated.claims().stream().map(ClaimView::of).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken for a person: its number among theirs, its due-total (null when n/a) and date. */
@Entity
@Table(name = "person_statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "seq", nullable = false)
    private int seq;

    @Column(name = "total", precision = 14, scale = 2)
    private BigDecimal total;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, int seq, BigDecimal total, LocalDate takenOn) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.seq = seq;
        this.total = total;
        this.takenOn = takenOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public int getSeq() {
        return seq;
    }

    public BigDecimal getTotal() {
        return total;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    /** Move the statement to a person (on a sheet) under a number among theirs. */
    public void moveTo(String sheetId, Long personId, int seq) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.seq = seq;
    }
}
