 * every save, so an edit made from an older version is refused.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)

    /** Keep the person's due-total (null: n/a) as it stood on a day the sheet's today moves on from. */
